from test_coverage_runner_bounds import score
from oomwoo_sim_support import coverage_regression_runner as runner
from std_msgs.msg import Float32

def test_new_coverage_cannot_pass_with_the_preceding_efficiency(score):
    def update(node, tick):
        node.sweep_started = True
        if tick == 1:
            runner.CoverageRunner._on_eff(node, Float32(data=.805))
        elif tick == 2:
            runner.CoverageRunner._on_cov(node, Float32(data=.901))
        elif tick == 3:
            runner.CoverageRunner._on_eff(node, Float32(data=.799))
        node.sweep_complete = tick >= 4
    code, report, _ = score(wall=10.0, update=update)
    assert code == 1, report
